/*
 * A041960  Numerators of continued fraction convergents to sqrt(503).
 * https://oeis.org/A041960
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy, less
 * Formula:   not stated
 * Range:     u8 n <= 3, u16 n <= 7, u32 n <= 15, u64 n <= 31, u128 n <= 63,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: a(n) = numerator of the n-th convergent of sqrt(503),
 * i.e. of the continued fraction expansion of √503.
 * The continued fraction is generated by the usual
 * algorithm (m_{k+1} = d_k a_k - m_k, d_{k+1} = (D - m_{k+1}^2)/d_k,
 * a_{k+1} = ⌊(a0 + m_{k+1})/d_{k+1}⌋).
 * The numerators satisfy:
 *   p_{-2} = 0, p_{-1} = 1,
 *   p_k   = a_k * p_{k-1} + p_{k-2}   (k ≥ 0).
 *
 * This function computes p_n for any n ≥ 0, using only integer
 * arithmetic and the type seq_t supplied by the build system.
 */

#include <stdint.h>

seq_t a(idx_t n) {
    const uint64_t D = 503;
    const uint64_t a0 = 22;      /* ⌊√503⌋ */

    /* Convergents recurrence */
    seq_t p_prev2 = (seq_t)0; /* p_{-2} */
    seq_t p_prev1 = (seq_t)1; /* p_{-1} */
    seq_t p_curr  = (seq_t)0; /* placeholder */

    /* Contin. frac. generation */
    uint64_t m = 0;
    uint64_t d = 1;
    uint64_t a_curr = a0;

    for (idx_t i = 0; i <= n; ++i) {
        /* Compute p_i = a_i * p_{i-1} + p_{i-2} */
        p_curr = (seq_t)a_curr * p_prev1 + p_prev2;
        if (i == n)
            return p_curr;

        /* Advance continued fraction coefficients */
        uint64_t m_next = d * a_curr - m;
        uint64_t d_next = (D - m_next * m_next) / d;
        uint64_t a_next = (a0 + m_next) / d_next;

        /* Shift for next iteration */
        p_prev2 = p_prev1;
        p_prev1 = p_curr;
        m = m_next;
        d = d_next;
        a_curr = a_next;
    }

    /* Unreachable, but keep compiler quiet */
    return (seq_t)0;
}
